			exitFunc(1)
			return
		}
		indexFile := filepath.Join(vendorDir, "index.md")

		if _, err := os.Stat(indexFile); err == nil && !force {
			fmt.Printf("Bundle %q is already installed in %s (skipping)\n", entry.ID, vendorDisplay)
			skippedCount++
