			exitFunc(1)
			return
		}

		vb, err := okf.LoadBundle(staging.Dir)
		if err != nil {
			rollback()
			fmt.Fprintf(os.Stderr, "Error: bundle %q failed to load: %v (installation rolled back)\n", manifest.ID, err)
			exitFunc(1)
